/**
 * The cap is stored as atomic units with no token attached: one dollar ceiling,
 * kept at 6 decimals, over every stablecoin the wallet can spend. Naming USDC
 * in the output used to read as "USDC only" to an agent taking it literally —
 * one compared a USDT balance against a "USDC cap" and concluded USDT was
 * uncapped — so every user-facing figure is formatted here with no symbol and
 * the unit is spelt out as "in stablecoins" where it matters.
 *
 * The list is the set every `--token` option offers, and no wider. USDm is in
 * core's token table but is 18-decimal and has no EIP-3009, so no x402 path
 * will sign for it and no `--token` choice accepts it; naming it here would
 * send a reader to a `--token USDm` that is refused. Whatever does reach the
 * ledger is reserved from the human amount at 6 decimals (see `buy send` and
 * the MCP send tool), so the cap is one number regardless of a token's own
 * precision.
 */
export declare const CAP_STABLECOINS = "stablecoins (USDC/USDT/USAT)";
